'use strict';
(function(){const T=JourneyTraits,oldIcon=traitIcon;traitIcon=function(id){return T.D[id]?.icon||oldIcon(id)||'star';};let previousModal=null,filterPositions=[];
function label(d){return L(d.en,d.pt);}function countsNow(){if(battle?.traits54)return battle.traits54.counts[0];if(!S)return{};if(selected){const id=selectedUid();if(id)return G.traitPreview(S,id).after;}return G.counts(S.board.filter(Boolean).map(id=>G.card(S,id)));}
traitRibbon=function(){const n=countsNow();return '<div class="trait-ribbon traits54-ribbon">'+Object.entries(T.categories).map(([id,d])=>{const active=Object.values(T.D).filter(t=>t.category===id&&T.tier(n,t.id)>0).length;return '<button class="traits54-category" data-act="traits54-category" data-id="'+id+'">'+Icon({faction:'units',attribute:'sword',temperament:'star'}[id])+'<span>'+label(d)+'</span><b>'+active+'</b></button>';}).join('')+'</div>';};
function remember(){const el=document.querySelector('#overlay>.modal');if(el&&!el.classList.contains('journey-panel')){const copy=el.cloneNode(true);copy.querySelector('.close')?.remove();previousModal={html:copy.innerHTML,cls:el.className};}else previousModal=null;}
function back(){if(previousModal){const p=previousModal;previousModal=null;openModal(p.html);document.querySelector('#overlay>.modal').className=p.cls;}else closeModal();}
function detailTrait(id){const d=T.D[id];if(!d)return;const n=countsNow()[id]||0,k=T.tier(countsNow(),id);journeyPanel(label(d),'<div class="traits54-info">'+Icon(d.icon)+'<span>'+label(T.categories[d.category])+'</span></div><p>'+esc(L(d.desc,d.descPT))+'</p><p class="traits54-rule">'+(d.thresholds.length?L('Different fielded characters: ','Personagens diferentes em campo: ')+n+' · '+L('Tiers: ','Patamares: ')+d.thresholds.join(' / ')+' · '+(k?L('Active tier ','Patamar ativo ')+k:L('Inactive','Inativo')):L('Faction identity only; no collective bonus yet.','Identificação de facção; ainda sem bônus coletivo.'))+'</p><p class="panel-hint">'+L('Only matching members benefit. Repeated copies, fusion copies and reserve units do not add to the count. The higher tier replaces the lower. Battle tiers stay fixed for the round.','Só os integrantes recebem o benefício. Cópias repetidas, constituintes de fusão e unidades no banco não aumentam a contagem. O patamar maior substitui o menor. No combate, os patamares permanecem fixos durante a rodada.')+'</p>',metaButton('traits54-back',L('Back','Voltar'),'','primary'));}
function category(id){previousModal=null;const n=countsNow(),all=Object.values(T.D).filter(d=>d.category===id);journeyPanel(label(T.categories[id]),'<div class="traits54-list">'+all.map(d=>'<button data-act="traits54-open" data-id="'+d.id+'" class="'+(T.tier(n,d.id)?'active':'')+'">'+Icon(d.icon)+'<span><b>'+esc(label(d))+'</b><small>'+esc(L(d.desc,d.descPT))+'</small></span><strong>'+(n[d.id]||0)+(d.thresholds.length?' / '+d.thresholds.join('·'):'')+'</strong></button>').join('')+'</div>',metaButton('close',L('Back','Voltar'),'','primary'));}
const collection=collectionView;collectionView=function(){const rows=[...document.querySelectorAll('.meta-screen .meta-filters')],top=document.querySelector('#screen-content')?.scrollTop||0;if(rows.length)filterPositions=rows.map(el=>el.scrollLeft);const was=activeMetaScreen==='collection';collection();const apply=()=>{[...document.querySelectorAll('.meta-screen .meta-filters')].forEach((el,i)=>el.scrollLeft=filterPositions[i]||0);if(was&&document.querySelector('#screen-content'))document.querySelector('#screen-content').scrollTop=top;};apply();requestAnimationFrame(apply);for(const el of document.querySelectorAll('.collection-entry')){const id=el.querySelector('[data-act="meta-info"]')?.dataset.id,a=T.assignments[id],caption=el.querySelector(':scope>small');if(a&&caption)caption.textContent=a.faction+(G.BY[id].order?' · '+(G.BY[id].order==='blackfang'?'Blackfang':'Dawncrest'):'');}};
const guard=JourneyTraining.guard;JourneyTraining.guard=function(e){const el=e.target.closest?.('[data-act]'),d=el?.dataset;if(!d)return guard(e);if(d.act!=='trait'&&!d.act.startsWith('traits54-'))return guard(e);if(e.type!=='click'&&!(e.type==='keydown'&&['Enter',' '].includes(e.key)))return guard(e);e.preventDefault();e.stopImmediatePropagation();if(el.disabled)return true;if(d.act==='trait'){remember();detailTrait(d.id);}else if(d.act==='traits54-category')category(d.id);else if(d.act==='traits54-open')detailTrait(d.id);else if(d.act==='traits54-back')back();return true;};
})();
